HEADER = '''# Copyright (C) 2026 the Typhon authors
# Ported from scipy 1.18.1 (BSD-3-Clause)
# Generated by test/scipy/gen_special_expected.py (scipy 1.18.1); do not edit.
import numpy as np
import scipy.special as sp

NFAIL = [0]

def chk(expr: str, got: float, ref: float, rtol: float):
    if ref != ref:
        if got == got:
            print('FAIL', expr, got, 'expected nan')
            NFAIL[0] += 1
        return
    if ref == float('inf') or ref == -float('inf'):
        if got != ref:
            print('FAIL', expr, got, 'expected', ref)
            NFAIL[0] += 1
        return
    if not (abs(got - ref) <= rtol * abs(ref) + 1e-300):
        print('FAIL', expr, got, 'expected', ref, 'rel', abs(got - ref) / max(abs(ref), 1e-300))
        NFAIL[0] += 1

def chkv(expr: str, got, ref: List[float], rtol: float):
    g = np.asarray(got).ravel()
    if len(g) != len(ref):
        print('FAIL', expr, 'length', len(g), len(ref))
        NFAIL[0] += 1
        return
    for i in range(len(ref)):
        chk(expr, float(g[i]), ref[i], rtol)
'''

def L(x):
    # expression literal for a float/int argument
    if isinstance(x, float):
        if math.isnan(x):
            return "float('nan')"
        if math.isinf(x):
            return "float('inf')" if x > 0 else "-float('inf')"
    return repr(x)

def fmt(v):
    v = float(v)
    if math.isnan(v):
        return "float('nan')"
    if math.isinf(v):
        return "float('inf')" if v > 0 else "-float('inf')"
    return repr(v)

class Gen:
    def __init__(self, name):
        self.name = name
        self.blocks = []
        self.cur = None

    def block(self, title):
        self.cur = [title, []]
        self.blocks.append(self.cur)

    def s(self, expr, rtol=1e-13):
        v = eval(expr, {'sp': sp, 'np': np})
        self.cur[1].append(f"    chk({expr!r}, {expr}, {fmt(v)}, {rtol!r})")

    def v(self, expr, rtol=1e-13):
        v = np.asarray(eval(expr, {'sp': sp, 'np': np}), dtype=float).ravel()
        lst = '[' + ', '.join(fmt(e) for e in v) + ']'
        self.cur[1].append(f"    chkv({expr!r}, {expr}, {lst}, {rtol!r})")

    def write(self):
        out = [HEADER]
        for title, lines in self.blocks:
            fn = 'test_' + title
            out.append('@test')
            out.append(f'def {fn}():')
            out.extend(lines)
            out.append('    assert NFAIL[0] == 0')
            out.append(f'{fn}()')
            out.append('')
        with open(os.path.join(HERE, self.name), 'w') as f:
            f.write('\n'.join(out))

